import 'dart:math' as math;

import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';


/// A driving car: spinning wheels, suspension bounce, scrolling road and
/// speed lines. Built from the layers of `Car.svg`.
///
/// ```dart
/// const AnimatedCar(width: 320)
/// ```
class AnimatedCar extends StatefulWidget {
  const AnimatedCar({
    super.key,
    this.width = 320,
    this.duration = const Duration(milliseconds: 900),
    this.playing = true,
    this.showRoad = true,
    this.showSpeedLines = true,
    this.mirrored = false,
    this.roadColor = const Color(0xFFCFD8DC),
  });

  /// Total widget width (includes the space behind the car for speed lines).
  final double width;

  /// Time for ONE full wheel revolution. Shorter = faster car.
  final Duration duration;

  /// Pause / resume the animation.
  final bool playing;

  final bool showRoad;
  final bool showSpeedLines;

  /// true = car sprite flipped (faces right). Wheels, road and speed lines
  /// always move consistently with the driving direction.
  /// false (default) = car drives to the LEFT, matching the Figma design.
  final bool mirrored;
  final Color roadColor;

  @override
  State<AnimatedCar> createState() => _AnimatedCarState();
}

class _AnimatedCarState extends State<AnimatedCar>
    with SingleTickerProviderStateMixin {
  // World units = the SVG's coordinate space.
  static const double _padLeft = 60; // room for speed lines (same on both sides => car stays centered)
  static const double _carW = 213;
  static const double _carH = 83;
  static const double _roadH = 18;
  static const double _worldW = _padLeft + _carW + _padLeft;
  static const double _worldH = _carH + _roadH;

  // Wheel geometry measured from the SVG.
  static const double _wheelBox = 38;
  static const Offset _rearCenter = Offset(36.9, 64.2);
  static const Offset _frontCenter = Offset(175.03, 64.2);

  late final AnimationController _c;

  @override
  void initState() {
    super.initState();
    _c = AnimationController(vsync: this, duration: widget.duration);
    if (widget.playing) _c.repeat();
  }

  @override
  void didUpdateWidget(AnimatedCar old) {
    super.didUpdateWidget(old);
    if (old.duration != widget.duration) _c.duration = widget.duration;
    if (widget.playing && !_c.isAnimating) {
      _c.repeat();
    } else if (!widget.playing && _c.isAnimating) {
      _c.stop();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final s = widget.width / _worldW;

    // Static SVG layers are built once, outside the animation builder.
    final base = SvgPicture.string(carBaseSvg, width: _carW * s, height: _carH * s);
    final body = SvgPicture.string(carBodySvg, width: _carW * s, height: _carH * s);
    final rearWheel = SvgPicture.string(carRearWheelSvg, width: _wheelBox * s, height: _wheelBox * s);
    final frontWheel = SvgPicture.string(carFrontWheelSvg, width: _wheelBox * s, height: _wheelBox * s);

    Widget wheel(Widget svg, Offset center, double angle) => Positioned(
      left: (center.dx - _wheelBox / 2) * s,
      top: (center.dy - _wheelBox / 2) * s,
      child: Transform.rotate(angle: angle, child: svg),
    );

    return RepaintBoundary(
      child: SizedBox(
        width: widget.width,
        height: _worldH * s,
        child: AnimatedBuilder(
          animation: _c,
          builder: (context, _) {
            final t = _c.value; // 0..1 == one wheel revolution
            // Positive = clockwise on screen. A car driving right spins its
            // wheels clockwise; driving left (the default) is counter-clockwise.
            // The sprite flip would reverse the spin, so counter that here.
            final spin = t * 2 * math.pi * (widget.mirrored ? 1 : -1);

            // Suspension bounce: integer multiples keep the loop seamless.
            final bounceY = (math.sin(t * 2 * math.pi * 4) * 0.6 +
                math.sin(t * 2 * math.pi * 7) * 0.25) *
                s;
            final pitch = math.sin(t * 2 * math.pi * 2) * 0.004;

            return Stack(
              clipBehavior: Clip.none,
              children: [
                Positioned.fill(
                  child: CustomPaint(
                    painter: _RoadPainter(
                      t: t,
                      scale: s,
                      worldW: _worldW,
                      padLeft: _padLeft,
                      groundY: 82.6,
                      roadColor: widget.roadColor,
                      showRoad: widget.showRoad,
                      showSpeedLines: widget.showSpeedLines,
                      drivesRight: widget.mirrored,
                    ),
                  ),
                ),
                Positioned(
                  left: _padLeft * s,
                  top: 0,
                  child: Transform.translate(
                    offset: Offset(0, bounceY),
                    child: Transform.flip(
                      flipX: widget.mirrored,
                      child: Transform.rotate(
                        angle: pitch,
                        child: SizedBox(
                          width: _carW * s,
                          height: _carH * s,
                          child: Stack(
                            clipBehavior: Clip.none,
                            children: [
                              base,
                              wheel(rearWheel, _rearCenter, spin),
                              wheel(frontWheel, _frontCenter, spin),
                              body,
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}

class _RoadPainter extends CustomPainter {
  _RoadPainter({
    required this.t,
    required this.scale,
    required this.worldW,
    required this.padLeft,
    required this.groundY,
    required this.roadColor,
    required this.showRoad,
    required this.showSpeedLines,
    required this.drivesRight,
  });

  final double t;
  final double scale;
  final double worldW;
  final double padLeft;
  final double groundY;
  final Color roadColor;
  final bool showRoad;
  final bool showSpeedLines;

  /// Direction of travel: dashes scroll opposite to it, speed lines trail
  /// behind the car on that side.
  final bool drivesRight;

  // Wheel circumference (r ~ 18.1). One revolution moves the road exactly
  // this far, so tyres never "slip". It equals 2 dash periods => seamless loop.
  static const double _circumference = 113.7;
  static const double _dashPeriod = _circumference / 2;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.scale(scale);

    if (showRoad) {
      final line = Paint()
        ..color = roadColor
        ..strokeWidth = 1.6
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(Offset(0, groundY), Offset(worldW, groundY), line);

      final dash = Paint()
        ..color = roadColor
        ..strokeWidth = 2.4
        ..strokeCap = StrokeCap.round;
      // Road scrolls opposite to the driving direction.
      final shift = drivesRight ? -1.0 : 1.0;
      final offset = (t * _circumference * shift) % _dashPeriod;
      for (double x = -offset - _dashPeriod; x < worldW; x += _dashPeriod) {
        canvas.drawLine(
          Offset(x, groundY + 9),
          Offset(x + _dashPeriod * 0.5, groundY + 9),
          dash,
        );
      }
    }

    if (showSpeedLines) {
      final worldRight = padLeft + 213; // car's right edge in world units
      // (y, length, speed multiplier (integer => seamless), phase)
      const lines = [
        (28.0, 26.0, 1, 0.00),
        (46.0, 34.0, 2, 0.35),
        (60.0, 22.0, 1, 0.65),
        (38.0, 18.0, 2, 0.85),
      ];
      for (final (y, len, speed, phase) in lines) {
        final p = (t * speed + phase) % 1.0;
        // Lines spawn just behind the car and drift further back, on the
        // trailing side of the driving direction.
        final double x;
        if (drivesRight) {
          x = padLeft - 6 - p * (padLeft - 4); // trail to the left
        } else {
          x = worldRight + 6 + p * (padLeft - 4); // trail to the right
        }
        final alpha = (1 - p) * (p < 0.1 ? p / 0.1 : 1);
        canvas.drawLine(
          Offset(x, y),
          Offset(x - len, y),
          Paint()
            ..color = roadColor.withAlpha((alpha.clamp(0.0, 1.0) * 255).round())
            ..strokeWidth = 2
            ..strokeCap = StrokeCap.round,
        );
      }
    }
  }

  @override
  bool shouldRepaint(_RoadPainter old) =>
      old.t != t || old.scale != scale || old.roadColor != roadColor;
}

/// Demo screen: speed slider + play/pause.
class AnimatedCarDemo extends StatefulWidget {
  const AnimatedCarDemo({super.key});

  @override
  State<AnimatedCarDemo> createState() => _AnimatedCarDemoState();
}

class _AnimatedCarDemoState extends State<AnimatedCarDemo> {
  bool _playing = true;
  double _revMs = 900;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            AnimatedCar(
              width: 340,
              playing: _playing,
              duration: Duration(milliseconds: _revMs.round()),
            ),
            const SizedBox(height: 32),
            SizedBox(
              width: 260,
              child: Slider(
                min: 300,
                max: 2000,
                value: 2300 - _revMs, // right = faster
                onChanged: (v) => setState(() => _revMs = 2300 - v),
              ),
            ),
            FilledButton(
              onPressed: () => setState(() => _playing = !_playing),
              child: Text(_playing ? 'Pause' : 'Play'),
            ),
          ],
        ),
      ),
    );
  }
}

